		{"zero capacity", 0, 1, nil, true},
		{"negative capacity", -1, 1, nil, true},
		{"zero rate", 1, 0, nil, true},
		{"negative rate", 1, -1, nil, true},
		{"nil clock ok", 1, 1, nil, false},
