type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clock := newFakeClock()
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 10, 1, nil, true},
		{"zero capacity", 0, 1, clock, true},
		{"negative capacity", -1, 1, clock, true},
		{"zero rate", 10, 0, clock, true},
		{"negative rate", 10, -1, clock, true},
		{"valid", 10, 2, clock, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			b, err := New(tc.capacity, tc.rate, tc.clock)
			if (err != nil) != tc.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tc.wantErr)
			}
			if !tc.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

type step struct {
	advance time.Duration
	n       int
	want    bool
}

func TestAllowN(t *testing.T) {
	cases := []struct {
		name     string
		capacity int
		rate     float64
		steps    []step
	}{
		{
			name:     "drains then denies",
			capacity: 2,
			rate:     1,
			steps: []step{
				{0, 1, true},
				{0, 1, true},
				{0, 1, false},
			},
		},
		{
			name:     "refills over time",
			capacity: 2,
			rate:     2,
			steps: []step{
				{0, 2, true},
				{0, 1, false},
				{500 * time.Millisecond, 1, true},
			},
		},
		{
			name:     "caps refill at capacity",
			capacity: 1,
			rate:     10,
			steps: []step{
				{0, 1, true},
				{time.Second, 1, true},
				{0, 1, false},
			},
		},
		{
			name:     "nonpositive n always allowed",
			capacity: 1,
			rate:     1,
			steps: []step{
				{0, 0, true},
				{0, -5, true},
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clock := newFakeClock()
			b, err := New(tc.capacity, tc.rate, clock)
			if err != nil {
				t.Fatal(err)
			}
			for i, s := range tc.steps {
				clock.Advance(s.advance)
				if got := b.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllowNConcurrent(t *testing.T) {
	clock := newFakeClock()
	b, err := New(100, 1000, clock)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0
	for i := 0; i < 200; i++ {
